// smoke.spec.js — tool-specific checks for Compress Image to Exact KB, using fictional fixtures in tests/fixtures/
// (harbor-point.jpg and demo-logo.png are generated by tests/make-fixtures.js).
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');

const fixture = (name) => path.join(__dirname, 'fixtures', name);
const KB = 1000; // the tool treats KB as 1,000 bytes so results pass either convention

async function readDownload(download) {
  return fs.readFileSync(await download.path());
}

function isJpeg(bytes) { return bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff; }

// Builds a JPEG with an EXIF APP1 block (Orientation + GPS coordinates) from a baseline JPEG, so the
// metadata-stripping tests have a fictional "phone photo" without copying anything from a real device.
function withExif(jpeg, orientation = 1) {
  const gpsOffset = 8 + 2 + 2 * 12 + 4;
  const dataOffset = gpsOffset + 2 + 4 * 12 + 4;
  const t = Buffer.alloc(dataOffset + 48);
  t.write('MM', 0); t.writeUInt16BE(42, 2); t.writeUInt32BE(8, 4);
  let p = 8;
  t.writeUInt16BE(2, p); p += 2;
  t.writeUInt16BE(0x0112, p); t.writeUInt16BE(3, p + 2); t.writeUInt32BE(1, p + 4); t.writeUInt16BE(orientation, p + 8); p += 12;
  t.writeUInt16BE(0x8825, p); t.writeUInt16BE(4, p + 2); t.writeUInt32BE(1, p + 4); t.writeUInt32BE(gpsOffset, p + 8); p += 12;
  t.writeUInt32BE(0, p); p += 4;
  t.writeUInt16BE(4, p); p += 2;
  let d = dataOffset;
  for (const [tag, type, count, val] of [[1, 2, 2, 'N\0'], [2, 5, 3, null], [3, 2, 2, 'E\0'], [4, 5, 3, null]]) {
    t.writeUInt16BE(tag, p); t.writeUInt16BE(type, p + 2); t.writeUInt32BE(count, p + 4);
    if (type === 2) t.write(val, p + 8, 'ascii');
    else { t.writeUInt32BE(d, p + 8); for (const [n, dn] of [[51, 1], [30, 1], [0, 1]]) { t.writeUInt32BE(n, d); t.writeUInt32BE(dn, d + 4); d += 8; } }
    p += 12;
  }
  t.writeUInt32BE(0, p);
  const body = Buffer.concat([Buffer.from('Exif\0\0'), t]);
  const app1 = Buffer.concat([Buffer.from([0xff, 0xe1, (body.length + 2) >> 8, (body.length + 2) & 0xff]), body]);
  return Buffer.concat([jpeg.subarray(0, 2), app1, jpeg.subarray(2)]);
}
function hasExif(bytes) { return bytes.includes('Exif'); }
function isWebp(bytes) { return bytes.subarray(0, 4).toString('ascii') === 'RIFF' && bytes.subarray(8, 12).toString('ascii') === 'WEBP'; }

async function compressSample(page) {
  await page.goto('./');
  await page.setInputFiles('#file-input', fixture('harbor-point.jpg'));
  const card = page.locator('.kb-card').first();
  await expect(card).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
  return card;
}

test.describe('Compress Image to Exact KB', () => {
  test('the ~3 MB sample photo at 100 KB becomes a downloadable JPEG between 20 and 100 KB', async ({ page }) => {
    const original = fs.statSync(fixture('harbor-point.jpg')).size;
    expect(original).toBeGreaterThan(2_500_000);
    await page.goto('./');
    await expect(page.locator('input[name="target"][value="100000"]')).toBeChecked();
    await expect(page.locator('#format')).toHaveValue('jpeg');
    const card = await compressSample(page);
    const [download] = await Promise.all([page.waitForEvent('download'), card.locator('.kb-dl').click()]);
    const bytes = await readDownload(download);
    expect(isJpeg(bytes)).toBe(true);
    expect(bytes.length).toBeLessThanOrEqual(100 * KB);
    expect(bytes.length).toBeGreaterThan(20 * KB);
    expect(Number(await card.getAttribute('data-size'))).toBe(bytes.length);
  });

  test('result card shows original size, new size, percent saved, quality and dimensions', async ({ page }) => {
    const card = await compressSample(page);
    const stats = card.locator('.kb-stats');
    await expect(stats).toBeVisible();
    await expect(stats.locator('[data-k="orig"]')).toContainText(/2\.\d MB/);
    await expect(stats.locator('[data-k="new"]')).toContainText(/\d+ KB/);
    await expect(stats.locator('[data-k="saved"]')).toHaveText(/^9\d%$/);
    await expect(stats.locator('[data-k="quality"]')).toHaveText(/^\d{2}%$/);
    await expect(stats.locator('[data-k="dims"]')).toContainText(/3000 × 2000( → \d+ × \d+)? px/);
    for (const label of ['Original size', 'New size', 'Saved', 'Quality', 'Dimensions']) {
      await expect(stats).toContainText(label);
    }
  });

  test('switching the target to 50 KB and pressing compress again yields a file under 50 KB', async ({ page }) => {
    const card = await compressSample(page);
    const first = Number(await card.getAttribute('data-size'));
    await page.locator('label.kb-chip', { hasText: '50 KB' }).click();
    await expect(page.locator('input[name="target"][value="50000"]')).toBeChecked();
    await page.getByRole('button', { name: /Compress again/ }).click();
    await expect(card).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
    await expect(card.locator('.kb-dl')).toHaveText('Download harbor-point-50kb.jpg');
    const [download] = await Promise.all([page.waitForEvent('download'), card.locator('.kb-dl').click()]);
    const bytes = await readDownload(download);
    expect(download.suggestedFilename()).toBe('harbor-point-50kb.jpg');
    expect(isJpeg(bytes)).toBe(true);
    expect(bytes.length).toBeLessThan(50 * KB);
    expect(bytes.length).toBeLessThan(first);
  });

  test('dropping a text file shows a clear unsupported-file message and no download button', async ({ page }) => {
    await page.goto('./');
    const text = fs.readFileSync(fixture('sample.txt'), 'utf8');
    await page.evaluate((content) => {
      const dt = new DataTransfer();
      dt.items.add(new File([content], 'notes.txt', { type: 'text/plain' }));
      document.getElementById('dropzone').dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
    }, text);
    const alert = page.locator('#results .alert.alert--error');
    await expect(alert).toBeVisible();
    await expect(alert).toContainText('notes.txt');
    await expect(alert).toContainText(/not a supported image/i);
    await expect(page.locator('.kb-dl')).toHaveCount(0);
    await expect(page.locator('.kb-card')).toHaveCount(0);
  });

  test('empty and HEIC files are rejected with their own messages', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', [
      { name: 'blank.jpg', mimeType: 'image/jpeg', buffer: Buffer.alloc(0) },
      { name: 'sample.heic', mimeType: 'image/heic', buffer: fs.readFileSync(fixture('sample.heic')) },
    ]);
    await expect(page.locator('#results .alert--error')).toHaveCount(2);
    await expect(page.locator('#results')).toContainText('blank.jpg is empty');
    await expect(page.locator('#results')).toContainText(/HEIC photos cannot be read/);
    await expect(page.locator('.kb-dl')).toHaveCount(0);
  });

  test('before and after previews are visible and the layout fits 390px', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    const card = await compressSample(page);
    for (const sel of ['.kb-before', '.kb-after']) {
      const img = card.locator(sel);
      await expect(img).toBeVisible();
      await expect.poll(() => img.evaluate((el) => el.complete && el.naturalWidth)).toBeGreaterThan(0);
    }
    await expect(card.locator('.kb-dl')).toBeVisible();
    await page.locator('.kb-advanced summary').click();
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    const box = await card.boundingBox();
    expect(box.x).toBeGreaterThanOrEqual(0);
    expect(box.x + box.width).toBeLessThanOrEqual(390);
  });

  test('downloaded filename follows name-100kb.jpg and non-ASCII names are kept', async ({ page }) => {
    const card = await compressSample(page);
    const [download] = await Promise.all([page.waitForEvent('download'), card.locator('.kb-dl').click()]);
    expect(download.suggestedFilename()).toBe('harbor-point-100kb.jpg');

    await page.locator('#clear-btn').click();
    await page.setInputFiles('#file-input', { name: 'café photo.jpg', mimeType: 'image/jpeg', buffer: fs.readFileSync(fixture('harbor-point.jpg')) });
    const c2 = page.locator('.kb-card').first();
    await expect(c2).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
    const [d2] = await Promise.all([page.waitForEvent('download'), c2.locator('.kb-dl').click()]);
    expect(d2.suggestedFilename()).toBe('café photo-100kb.jpg');
  });

  test('transparent PNG gets the chosen background colour as JPEG; small files stay unchanged', async ({ page }) => {
    await page.goto('./');
    await page.locator('.kb-advanced summary').click();
    await page.locator('#background').evaluate((el) => { el.value = '#ff0000'; el.dispatchEvent(new Event('input', { bubbles: true })); });
    await page.locator('label.kb-chip', { hasText: '20 KB' }).click();
    await page.locator('#format').selectOption('jpeg');
    await page.setInputFiles('#file-input', fixture('demo-logo.png'));
    const card = page.locator('.kb-card').first();
    await expect(card).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
    const corner = await card.locator('.kb-after').evaluate(async (img) => {
      await img.decode();
      const c = document.createElement('canvas'); c.width = img.naturalWidth; c.height = img.naturalHeight;
      const g = c.getContext('2d'); g.drawImage(img, 0, 0);
      return [...g.getImageData(2, 2, 1, 1).data];
    });
    expect(corner[0]).toBeGreaterThan(220);
    expect(corner[1]).toBeLessThan(40);
    const [download] = await Promise.all([page.waitForEvent('download'), card.locator('.kb-dl').click()]);
    expect(download.suggestedFilename()).toBe('demo-logo-20kb.jpg');

    await page.locator('#clear-btn').click();
    await page.locator('#format').selectOption('original');
    await page.setInputFiles('#file-input', fixture('demo-logo.png'));
    await expect(card).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
    await expect(card.locator('.kb-notes')).toContainText(/Already under the target/);
    const [d2] = await Promise.all([page.waitForEvent('download'), card.locator('.kb-dl').click()]);
    expect(d2.suggestedFilename()).toBe('demo-logo-20kb.png');
    expect((await readDownload(d2)).equals(fs.readFileSync(fixture('demo-logo.png')))).toBe(true);
  });

  test('custom target, batch mode with download all, and the keyboard-operable drop zone', async ({ page }) => {
    await page.goto('./');
    await page.locator('#custom-size').fill('30');
    await expect(page.locator('#target-custom-radio')).toBeChecked();
    await page.setInputFiles('#file-input', [fixture('harbor-point.jpg'), fixture('sample.png')]);
    await expect(page.locator('.kb-card[data-state="done"]')).toHaveCount(2, { timeout: 45_000 });
    const sizes = await page.locator('.kb-card').evaluateAll((els) => els.map((e) => Number(e.dataset.size)));
    sizes.forEach((n) => expect(n).toBeLessThanOrEqual(30 * KB));
    const names = [];
    page.on('download', (d) => names.push(d.suggestedFilename()));
    await page.locator('#download-all').click();
    await expect.poll(() => names.length, { timeout: 10_000 }).toBe(2);
    expect(names.sort()).toEqual(['harbor-point-30kb.jpg', 'sample-30kb.jpg']);

    const [chooser] = await Promise.all([page.waitForEvent('filechooser'), page.locator('#dropzone').focus().then(() => page.keyboard.press('Enter'))]);
    expect(chooser.isMultiple()).toBe(true);
  });

  test('the empty-state sample link produces a compressed result without requesting any file', async ({ page }) => {
    await page.goto('./');
    const requests = [];
    page.on('request', (r) => { if (/fixtures/.test(r.url())) requests.push(r.url()); });
    await expect(page.locator('#empty-state')).toBeVisible();
    await page.getByRole('button', { name: 'Try a sample photo' }).click();
    const card = page.locator('.kb-card').first();
    await expect(card).toHaveAttribute('data-state', 'done', { timeout: 45_000 });
    await expect(card.locator('.kb-card__name')).toHaveText('harbor-point.jpg');
    expect(Number(await card.getAttribute('data-size'))).toBeLessThanOrEqual(100 * KB);
    expect(requests).toEqual([]);
    await expect(page.locator('#empty-state')).toBeHidden();
  });

  test('WebP output works in the worker path and lands under the target', async ({ page }) => {
    await page.goto('./');
    await page.locator('#format').selectOption('webp');
    await page.setInputFiles('#file-input', fixture('harbor-point.jpg'));
    const card = page.locator('.kb-card').first();
    await expect(card).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
    await expect(card.locator('.alert')).toHaveCount(0);
    const [download] = await Promise.all([page.waitForEvent('download'), card.locator('.kb-dl').click()]);
    const bytes = await readDownload(download);
    expect(download.suggestedFilename()).toBe('harbor-point-100kb.webp');
    expect(isWebp(bytes)).toBe(true);
    expect(bytes.length).toBeLessThanOrEqual(100 * KB);
    expect(bytes.length).toBeGreaterThan(10 * KB);

    // "Keep original type" with a WebP input must also produce WebP, not an error.
    await page.locator('#clear-btn').click();
    await page.locator('#format').selectOption('original');
    await page.locator('label.kb-chip', { hasText: '20 KB' }).click();
    await page.setInputFiles('#file-input', { name: 'photo.webp', mimeType: 'image/webp', buffer: bytes });
    await expect(card).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
    const [d2] = await Promise.all([page.waitForEvent('download'), card.locator('.kb-dl').click()]);
    const out = await readDownload(d2);
    expect(d2.suggestedFilename()).toBe('photo-20kb.webp');
    expect(isWebp(out)).toBe(true);
    expect(out.length).toBeLessThanOrEqual(20 * KB);
  });

  test('metadata (EXIF, GPS) is removed from every result, including files already under the target', async ({ page }) => {
    const source = fs.readFileSync(fixture('sample.jpg'));
    const tagged = withExif(source, 1);
    expect(hasExif(tagged)).toBe(true);
    expect(tagged.length).toBeLessThan(100 * KB);
    await page.goto('./');
    await page.setInputFiles('#file-input', { name: 'phone-photo.jpg', mimeType: 'image/jpeg', buffer: tagged });
    const card = page.locator('.kb-card').first();
    await expect(card).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
    await expect(card.locator('.kb-notes')).toContainText(/metadata/i);
    await expect(card.locator('[data-k="quality"]')).toHaveText('Unchanged original');
    const [download] = await Promise.all([page.waitForEvent('download'), card.locator('.kb-dl').click()]);
    const bytes = await readDownload(download);
    expect(download.suggestedFilename()).toBe('phone-photo-100kb.jpg');
    expect(isJpeg(bytes)).toBe(true);
    expect(hasExif(bytes)).toBe(false);
    expect(bytes.length).toBeLessThan(tagged.length);
    // The picture data itself is untouched: everything from the start-of-scan marker on is identical.
    const scan = (b) => b.subarray(b.indexOf(Buffer.from([0xff, 0xda])));
    expect(scan(bytes).equals(scan(tagged))).toBe(true);

    // A small photo whose EXIF rotates it is re-encoded instead, so it stays upright and still loses the tags.
    await page.locator('#clear-btn').click();
    await page.setInputFiles('#file-input', { name: 'rotated.jpg', mimeType: 'image/jpeg', buffer: withExif(source, 6) });
    await expect(card).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
    await expect(card.locator('[data-k="dims"]')).toContainText('400 × 640 px');
    await expect(card.locator('.kb-notes')).toContainText(/rotation/);
    const [d2] = await Promise.all([page.waitForEvent('download'), card.locator('.kb-dl').click()]);
    const out = await readDownload(d2);
    expect(hasExif(out)).toBe(false);
    expect(out.length).toBeLessThanOrEqual(100 * KB);

    // A large photo that is compressed normally also comes out without EXIF.
    await page.locator('#clear-btn').click();
    await page.setInputFiles('#file-input', { name: 'big.jpg', mimeType: 'image/jpeg', buffer: withExif(fs.readFileSync(fixture('harbor-point.jpg')), 1) });
    await expect(card).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
    const [d3] = await Promise.all([page.waitForEvent('download'), card.locator('.kb-dl').click()]);
    expect(hasExif(await readDownload(d3))).toBe(false);
  });

  test('an empty custom target shows one error and adds no half-finished card', async ({ page }) => {
    await page.goto('./');
    await page.locator('#target-custom-radio').check();
    await page.setInputFiles('#file-input', fixture('sample.jpg'));
    await expect(page.locator('#results .alert--error')).toHaveText(/custom target size/i);
    await expect(page.locator('.kb-card')).toHaveCount(0);
    await page.locator('#custom-size').fill('15');
    await page.setInputFiles('#file-input', fixture('sample.jpg'));
    const card = page.locator('.kb-card').first();
    await expect(card).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
    expect(Number(await card.getAttribute('data-size'))).toBeLessThanOrEqual(15 * KB);
  });

  test('a conversion that makes the file bigger says so instead of claiming 0% saved', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', fixture('sample.gif'));
    const card = page.locator('.kb-card').first();
    await expect(card).toHaveAttribute('data-state', 'done', { timeout: 30_000 });
    const size = Number(await card.getAttribute('data-size'));
    expect(size).toBeGreaterThan(fs.statSync(fixture('sample.gif')).size);
    expect(size).toBeLessThanOrEqual(100 * KB);
    await expect(card.locator('[data-k="saved"]')).toHaveText(/grew by \d+%/);
    await expect(card.locator('.kb-card__saved')).toHaveText(/^\+\d+%$/);
    await expect(card.locator('.kb-notes')).toContainText(/larger than the original/);
  });

  test('__demo shows a finished result from the bundled sample', async ({ page }) => {
    await page.goto('./');
    await page.evaluate(() => window.__demo());
    await expect(page.locator('.kb-card[data-state="done"]')).toHaveCount(1);
    await expect(page.locator('.kb-dl')).toHaveText('Download harbor-point-100kb.jpg');
  });
});
